// Modify your App.js or layout component
import React from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
// Import other components...

function App() {
  // Your state and other logic...
  
  return (
    <Router>
      <div className="app">
        <Header user={user} onLogout={handleLogout} />
        <div className="app-container">
          {/* Welcome message moved above sidebar */}
          {isAuthenticated && (
            <div className="welcome-banner">
              <h2>Welcome, {user?.username === 'doctor' ? 'ER Doctor' : 'ER Nurse'}</h2>
              <span className="user-role">{user?.username === 'doctor' ? 'Doctor' : 'Nurse'}</span>
              <button onClick={handleLogout} className="logout-button">Logout</button>
            </div>
          )}
          
          {isAuthenticated && <Sidebar />}
          <main className="main-content">
            <Routes>
              {/* Your routes... */}
            </Routes>
          </main>
        </div>
      </div>
    </Router>
  );
}

export default App;
